  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text.short {
  width: 60%;
}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ============================================
   View Transitions
   ============================================ */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-morph: 400ms;
  --duration-nav: 400ms;
}

/* Shared element morph animation */
::view-transition-group(.morph) {
  animation-duration: var(--duration-morph);
}

::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* Suspense reveal animations */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    400ms ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

/* Directional navigation animations */
::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    150ms ease-in both fade reverse,
    var(--duration-nav) ease-in-out both slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    210ms ease-out 150ms both fade,
    var(--duration-nav) ease-in-out both slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    150ms ease-in both fade reverse,
    var(--duration-nav) ease-in-out both slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    210ms ease-out 150ms both fade,
    var(--duration-nav) ease-in-out both slide;
}

@keyframes slide {
  from {
    translate: var(--slide-offset);
  }
  to {
    translate: 0;
  }
}

/* Header anchoring - prevent header from sliding during navigation */
::view-transition-group(site-header) {
  animation: none;
  z-index: 100;
}

::view-transition-old(site-header) {
  display: none;
}

::view-transition-new(site-header) {
  animation: none;
}

/* ============================================
   Reduced Motion Support
   ============================================ */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .product-detail {
    grid-template-columns: 1fr;
  }

  header {
    padding: 1rem;
  }

  main {
    padding: 1rem;
  }
}

